     @Test
     void escapesText() {
-        String html = renderer().renderFragment(frameOf(VStack.of(Text.of("<a & b>"))), 1);
+        String html = renderer().renderFragment(frameOf(VStack.children(Text.with(t -> t.text("<a & b>")))), 1);
         assertTrue(html.contains("&lt;a &amp; b&gt;"));
